import { decideWhatsApp } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round5-heldout-haiku/work/knock-g5-2/bot.mjs';
import assert from 'node:assert/strict';

const T0 = "1767272400";            // 2026-01-01T13:00:00Z
const at = (ms) => new Date(Date.parse("2026-01-01T13:00:00Z") + ms);
const H = 3600e3;
const c = (over = {}) => ({ optedIn: true, lastInboundTimestamp: T0, ...over });
const cases = [
  // [name, message, now, expected]
  ["template, opted in, no inbound", { type: "template", contact: c({ lastInboundTimestamp: null }) }, at(0), { allowed: true, reason: null }],
  ["template, opted in, window long closed", { type: "template", contact: c() }, at(100 * H), { allowed: true, reason: null }],
  ["text, 1h after inbound", { type: "text", contact: c() }, at(1 * H), { allowed: true, reason: null }],
  ["text, 23h59m59s after inbound", { type: "text", contact: c() }, at(24 * H - 1000), { allowed: true, reason: null }],
  ["text, exactly 24h after inbound", { type: "text", contact: c() }, at(24 * H), { allowed: false, reason: "customer_service_window_closed" }],
  ["text, 25h after inbound", { type: "text", contact: c() }, at(25 * H), { allowed: false, reason: "customer_service_window_closed" }],
  ["text, never wrote to us", { type: "text", contact: c({ lastInboundTimestamp: null }) }, at(0), { allowed: false, reason: "no_customer_message" }],
  ["text, inbound in the future", { type: "text", contact: c() }, at(-5000), { allowed: false, reason: "invalid_last_inbound_timestamp" }],
  ["text, ms-scale timestamp (13 digits)", { type: "text", contact: c({ lastInboundTimestamp: "1767272400000" }) }, at(0), { allowed: false, reason: "invalid_last_inbound_timestamp" }],
  ["text, non-numeric timestamp", { type: "text", contact: c({ lastInboundTimestamp: "abc" }) }, at(0), { allowed: false, reason: "invalid_last_inbound_timestamp" }],
  ["text, numeric (not string) timestamp", { type: "text", contact: c({ lastInboundTimestamp: 1767272400 }) }, at(0), { allowed: false, reason: "invalid_last_inbound_timestamp" }],
  ["text, not opted in, in window", { type: "text", contact: c({ optedIn: false }) }, at(1 * H), { allowed: false, reason: "not_opted_in" }],
  ["template, not opted in", { type: "template", contact: c({ optedIn: false }) }, at(0), { allowed: false, reason: "not_opted_in" }],
  ["template, optedIn is string 'true'", { type: "template", contact: c({ optedIn: "true" }) }, at(0), { allowed: false, reason: "not_opted_in" }],
  ["unknown type", { type: "image", contact: c() }, at(0), { allowed: false, reason: "unknown_message_type" }],
];
let fail = 0;
for (const [name, msg, now, want] of cases) {
  const got = decideWhatsApp(msg, now);
  try { assert.deepEqual(got, want); console.log("ok  ", name, JSON.stringify(got)); }
  catch { fail++; console.log("FAIL", name, JSON.stringify(got), "want", JSON.stringify(want)); }
}
assert.throws(() => decideWhatsApp({ type: "text", contact: c() }, "2026-01-01"), TypeError);
console.log("ok   invalid now throws TypeError");
console.log(fail ? `${fail} FAILED` : "all passed");
process.exitCode = fail ? 1 : 0;
EOF
node /tmp/bot-check/check.mjs; echo "exit=$?"; node -e 'console.log(new Date(1767272400*1000).toISOString())'

